"use strict";

// Rasterises the favicon SVGs into the PNG sizes browsers and mobile launchers
// actually ask for, then packs the small sizes into a real multi-resolution
// favicon.ico for bare /favicon.ico requests.
//
//   npm run icons
//
// Icons change rarely, so this is a standalone script rather than part of the
// default build — the generated files are committed alongside the sources.

const fs = require("fs/promises");
const path = require("path");
const sharp = require("sharp");

const root = path.join(__dirname, "..");
const emblem = path.join(root, "img", "el-castillo-emblem.svg");
const tight = path.join(root, "img", "favicon.svg");
const padded = path.join(root, "img", "icon-maskable.svg");
const outDir = path.join(root, "img", "favicons");

// Brand palette — keep in step with scss/_variables.scss
const CHARCOAL = "#1f1d19";

// Both favicon sources are composed from the navbar emblem so the tab icon and
// the header logo can never drift apart. The only thing added is an opaque
// charcoal plate: the emblem draws parchment on a transparent ground, which
// measures 1.02:1 against a white browser tab — invisible in a light-themed
// browser. The plate is the same colour the emblem already sits on in the nav,
// so the icon reproduces exactly how the logo reads in the header.
async function composeSources() {
  const svg = await fs.readFile(emblem, "utf8");

  // Take everything inside the root <svg> element, minus editor cruft
  const inner = svg
    .slice(svg.indexOf(">", svg.indexOf("<svg")) + 1, svg.lastIndexOf("</svg>"))
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<\/?(title|desc)>[\s\S]*?<\/\1>|<(title|desc)>[\s\S]*?<\/\2>/g, "")
    .trim();

  const wrap = (body, note) =>
    `<?xml version="1.0" encoding="UTF-8"?>\n` +
    `<!-- GENERATED by scripts/generate-icons.js — do not edit.\n` +
    `     Source: img/el-castillo-emblem.svg (the navbar logo).\n` +
    `     ${note} -->\n` +
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="48" height="48" role="img" aria-label="A.Garcia Welding">\n` +
    `  <rect width="48" height="48" fill="${CHARCOAL}"/>\n` +
    `${body}\n</svg>\n`;

  // Tight: emblem at native 42 units, centred on the 48 plate (3 units of air)
  await fs.writeFile(
    tight,
    wrap(
      `  <g transform="translate(3 3)">\n    ${inner}\n  </g>`,
      "Tight variant for browser tabs and favicon.ico."
    )
  );

  // Maskable: Android keeps only the centred 80% circle. The emblem's corner
  // brackets put ink right at the artboard corners, so the whole mark has to
  // shrink until its diagonal clears that circle. 0.64 lands 1.9px inside the
  // boundary at 512 — technically passing, but with no room for a launcher
  // that crops a little harder, so it comes down to 0.60 for ~15px of margin.
  await fs.writeFile(
    padded,
    wrap(
      `  <g transform="translate(24 24) scale(0.60) translate(-21 -21)">\n    ${inner}\n  </g>`,
      "Padded variant for iOS home screen and Android maskable icons."
    )
  );
}

// `density` scales librsvg's rasterisation of the 48-unit viewBox. Rendering at
// the target size directly keeps edges as crisp as the source allows.
const densityFor = (size) => Math.max(72, Math.round((size / 48) * 72));

async function png(src, size, file) {
  await sharp(src, { density: densityFor(size) })
    .resize(size, size)
    .png({ compressionLevel: 9 })
    .toFile(path.join(outDir, file));
  return file;
}

// ICO container. Vista and later accept PNG-compressed entries, so each size is
// embedded as a whole PNG rather than a BMP+mask pair.
function buildIco(entries) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // 1 = icon
  header.writeUInt16LE(entries.length, 4);

  const dir = Buffer.alloc(16 * entries.length);
  let offset = header.length + dir.length;

  entries.forEach((entry, i) => {
    const at = i * 16;
    // 0 encodes 256 in the ICO directory; every size here is smaller than that
    dir.writeUInt8(entry.size >= 256 ? 0 : entry.size, at);
    dir.writeUInt8(entry.size >= 256 ? 0 : entry.size, at + 1);
    dir.writeUInt8(0, at + 2); // palette entries
    dir.writeUInt8(0, at + 3); // reserved
    dir.writeUInt16LE(1, at + 4); // colour planes
    dir.writeUInt16LE(32, at + 6); // bits per pixel
    dir.writeUInt32LE(entry.data.length, at + 8);
    dir.writeUInt32LE(offset, at + 12);
    offset += entry.data.length;
  });

  return Buffer.concat([header, dir, ...entries.map((e) => e.data)]);
}

(async () => {
  await fs.mkdir(outDir, { recursive: true });
  await composeSources();

  const written = [];

  // Tight mark: browser tabs, bookmarks, search results
  for (const size of [16, 32, 48]) {
    written.push(await png(tight, size, `favicon-${size}.png`));
  }

  // Manifest "any" icons are displayed uncropped, so they take the tight mark —
  // a launcher that intends to crop uses the maskable entry below instead.
  written.push(await png(tight, 192, "icon-192.png"));
  written.push(await png(tight, 512, "icon-512.png"));

  // Padded mark for the surfaces that do crop: iOS rounds the home-screen icon,
  // and Android keeps only the centred 80% circle of a maskable icon.
  written.push(await png(padded, 180, "apple-touch-icon.png"));
  written.push(await png(padded, 512, "icon-maskable-512.png"));

  const icoEntries = [];
  for (const size of [16, 32, 48]) {
    icoEntries.push({
      size,
      data: await sharp(tight, { density: densityFor(size) })
        .resize(size, size)
        .png({ compressionLevel: 9 })
        .toBuffer()
    });
  }
  await fs.writeFile(path.join(root, "favicon.ico"), buildIco(icoEntries));

  console.log("icons written to img/favicons/:");
  written.forEach((f) => console.log("  " + f));
  console.log("  ../../favicon.ico (16, 32, 48)");
})().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
